export const MC_RIO_HTML = "<section class=\"mc-top\" aria-label=\"Behind an Edition: Rio de Janeiro\">\n  <div class=\"mc-top__main\">\n    <a class=\"mc-back\" href=\"/masterclasses\"><i aria-hidden=\"true\"></i><span>All masterclasses</span></a>\n    <h2 class=\"mc-top__title\"><span>Masterclass</span><span class=\"ms-it\">Behind an Edition:</span><span class=\"ms-it\">Rio de Janeiro</span></h2>\n    <div class=\"mc-top__tag\">Nightkeeper</div>\n  </div>\n  <aside class=\"mc-key\" aria-label=\"Key information\">\n    <h3 class=\"mc-key__title\">Key information</h3>\n    <div class=\"mc-key__text\">Step behind the scenes of MSNYE 2027 and follow the creation of an edition, from the first idea to the night itself, as the Creative Division shapes the Maison’s vision of celebration.</div>\n    <div class=\"mc-pick mc-pick--key is-single\"><span class=\"mc-pick__label\">MS House</span><div class=\"mc-pick__value\">MS House Paris</div></div>\n    <ul class=\"mc-meta\"><li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 4 2 9l10 5 10-5-10-5Z\"/><path d=\"M6 11.2V16c0 1.4 2.7 2.8 6 2.8s6-1.4 6-2.8v-4.8\"/><path d=\"M22 9v5.5\"/></svg><span>Masterclass Archives</span></li><li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></svg><span>120 minutes</span></li><li><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c2.5 2.5 3.8 5.5 3.8 9s-1.3 6.5-3.8 9c-2.5-2.5-3.8-5.5-3.8-9S9.5 5.5 12 3z\"/></svg><span data-mc-langs>English, French</span></li><li data-mc-price-row hidden><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M3 12.2V4.5c0-.8.7-1.5 1.5-1.5h7.7c.4 0 .8.2 1.1.4l7.8 7.8c.6.6.6 1.5 0 2.1l-7.7 7.7c-.6.6-1.5.6-2.1 0l-7.8-7.8c-.3-.3-.5-.6-.5-1z\"/><circle cx=\"7.8\" cy=\"7.8\" r=\"1.3\"/></svg><span data-mc-price></span></li></ul>\n    <div class=\"mc-key__note\">This masterclass is part of the Masterclass Archives and is no longer open for booking.</div><a class=\"mc-btn mc-btn--line mc-key__btn\" href=\"/masterclasses\">Discover our masterclasses</a>\n  </aside>\n</section>\n<section class=\"mc-media\"><img src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" alt=\"Behind an Edition: Rio de Janeiro\" loading=\"eager\" draggable=\"false\"></section>\n<section class=\"mc-story\">\n  <div class=\"mc-story__lead\">Step behind the scenes of MSNYE 2027 and follow the creation of an edition, from the first idea to the night itself. The masterclass retraces how the Creative Division shaped the Maison’s vision of celebration in Rio de Janeiro.</div>\n  <div class=\"mc-story__body\">Sketches, moodboards and production plans reveal each step of the journey, and the decisions that turned an intuition into a night. An exclusive insight into the making of an edition, kept in the Masterclass Archives.</div>\n</section>\n<section class=\"mc-faq\" aria-label=\"Frequently asked questions\">\n  <h2 class=\"mc-faq__title\"><span>Masterclasses</span><span class=\"ms-it\">Frequently asked questions</span></h2>\n  <div class=\"mc-faq__list\"><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a0\" id=\"mc-q0\"><span>How do I book a masterclass?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a0\" role=\"region\" aria-labelledby=\"mc-q0\" hidden><div>Choose your MS House and select Book now. From your MS Account, send your booking request with the number of places. Our team confirms your booking by email, and you can follow it at any time from your MS Account.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a1\" id=\"mc-q1\"><span>When do I pay for my masterclass?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a1\" role=\"region\" aria-labelledby=\"mc-q1\" hidden><div>Once your booking is confirmed, you complete the payment by card from your MS Account. Payments are processed by our secure payment provider, Stripe, and Maison Sanguine does not store card details.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a2\" id=\"mc-q2\"><span>Do I need an MS Account to book?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a2\" role=\"region\" aria-labelledby=\"mc-q2\" hidden><div>Yes. Each booking is nominative and is managed from your MS Account, where you will find your confirmation, your payment and the details of your masterclass.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a3\" id=\"mc-q3\"><span>Can I change or cancel my booking?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a3\" role=\"region\" aria-labelledby=\"mc-q3\" hidden><div>You can change or cancel your booking free of charge up to three days before the masterclass, from your MS Account or by contacting the MS House. The price paid is then refunded in full. No refund is due for a cancellation made less than three days before the masterclass or in the event of absence.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a4\" id=\"mc-q4\"><span>Is there a minimum age to take part?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a4\" role=\"region\" aria-labelledby=\"mc-q4\" hidden><div>Masterclasses are reserved for participants aged 21 or older. Our teams may ask you to present an official identity document on arrival.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a5\" id=\"mc-q5\"><span>Can I come with someone?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a5\" role=\"region\" aria-labelledby=\"mc-q5\" hidden><div>Yes. Each booking can include up to two places. The full name of the second participant is requested when you book.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a6\" id=\"mc-q6\"><span>In which languages are the masterclasses offered?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a6\" role=\"region\" aria-labelledby=\"mc-q6\" hidden><div>The languages available are indicated for each MS House in the key information of every masterclass.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a7\" id=\"mc-q7\"><span>What happens if Maison Sanguine cancels the masterclass?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a7\" role=\"region\" aria-labelledby=\"mc-q7\" hidden><div>You will be offered a new date or a full refund of the price paid, at your choice. Refunds are made to the card used for the payment within fifteen days.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a8\" id=\"mc-q8\"><span>Should I arrive early?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a8\" role=\"region\" aria-labelledby=\"mc-q8\" hidden><div>We recommend arriving ten minutes before the start. Access may be refused, without refund, to participants arriving more than ten minutes after the scheduled time.</div></div></div><div class=\"mc-faq__item\"><h3 class=\"mc-faq__q\"><button type=\"button\" aria-expanded=\"false\" aria-controls=\"mc-a9\" id=\"mc-q9\"><span>Where can I find the terms of sale?</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><path d=\"M10 2v16M2 10h16\"/></svg></button></h3><div class=\"mc-faq__a\" id=\"mc-a9\" role=\"region\" aria-labelledby=\"mc-q9\" hidden><div>All the conditions of booking, payment and cancellation are set out in our <a href=\"/legal/masterclasses-terms-of-sale\">Masterclasses Terms of Sale</a>.</div></div></div></div>\n</section>\n<section class=\"ms-nl\">\n  <h2 class=\"ms-nl__title\"><span>Get the</span> <span class=\"ms-it\">Latest News</span></h2>\n  <div class=\"ms-nl__text\">Be the first to receive the latest news on our brand, products and upcoming events.</div>\n  <a class=\"ms-nl__btn\" href=\"https://maisonsanguine.com/form/newsletter-subscription\">Subscribe</a>\n</section>\n<script type=\"application/json\" id=\"mc-data\">{}</script>"

export const MC_PAGE_APP = "(function(){\n  var el=document.getElementById('mc-data');if(!el||el.getAttribute('data-ready'))return;el.setAttribute('data-ready','1');\n  var D=JSON.parse(el.textContent),P={};try{P=JSON.parse((document.getElementById('mc-prices')||{}).textContent||'{}')}catch(e){}\n  var sels=[].slice.call(document.querySelectorAll('[data-mc-house]')),books=[].slice.call(document.querySelectorAll('[data-mc-book]'));\n  var langs=document.querySelector('[data-mc-langs]'),price=document.querySelector('[data-mc-price]'),prow=document.querySelector('[data-mc-price-row]');\n  function set(h){\n    var d=D[h];if(!d)return;\n    sels.forEach(function(s){s.value=h});\n    if(langs)langs.textContent=d.languages;\n    if(prow){var v=P[d.edition];prow.hidden=!v;if(v)price.textContent=v}\n    books.forEach(function(b){var u=b.getAttribute('href').replace(/edition=[^&#]*/,'edition='+d.edition);b.setAttribute('href',u)});\n  }\n  sels.forEach(function(s){\n    if(s.options.length<2)s.closest('.mc-pick').classList.add('is-single');\n    s.addEventListener('change',function(){set(s.value)});\n  });\n  var want=new URLSearchParams(location.search).get('house');\n  set(D[want]?want:sels.length?sels[0].value:'');\n  [].forEach.call(document.querySelectorAll('.mc-faq__q button'),function(b){\n    b.addEventListener('click',function(){\n      var a=document.getElementById(b.getAttribute('aria-controls')),o=b.getAttribute('aria-expanded')!=='true';\n      b.setAttribute('aria-expanded',o?'true':'false');\n      if(o){a.hidden=false;a.style.height='0px';requestAnimationFrame(function(){a.style.height=a.scrollHeight+'px'})}\n      else{a.style.height=a.scrollHeight+'px';requestAnimationFrame(function(){a.style.height='0px'})}\n    });\n  });\n  [].forEach.call(document.querySelectorAll('.mc-faq__a'),function(a){a.addEventListener('transitionend',function(){if(a.style.height==='0px')a.hidden=true;else a.style.height='auto'})});\n  var bar=document.querySelector('.mc-bar'),key=document.querySelector('.mc-key'),foot=document.getElementById('ms-foot')||document.querySelector('footer');\n  if(bar&&key&&'IntersectionObserver' in window){\n    var past=false,end=false;\n    function upd(){var on=past&&!end;bar.hidden=false;bar.classList.toggle('is-on',on);bar.setAttribute('aria-hidden',on?'false':'true');[].forEach.call(bar.querySelectorAll('a,select'),function(n){n.tabIndex=on?0:-1})}\n    new IntersectionObserver(function(es){es.forEach(function(x){past=!x.isIntersecting&&x.boundingClientRect.top<0});upd()}).observe(key);\n    var nl=document.querySelector('section.ms-nl');\n    if(nl)new IntersectionObserver(function(es){es.forEach(function(x){end=x.isIntersecting||x.boundingClientRect.top<0});upd()}).observe(nl);\n    upd();\n  }\n})();"
